      dissolvedOrganicCarbonConsumedKgC: 1,
      dissolvedInorganicCarbonProducedKgC: .9,
      dissolvedOxygenConsumedKgO2:
        floodplainRespiration.AEROBIC_OXYGEN_KG_O2_PER_KG_C
